// Service worker for blog.liam.kim. Served at /sw.min.js, the path the old Chirpy site used,
// so browsers that still hold the old worker replace it on their next update check.
// `__BUILD_ID__` is replaced after the build by src/integrations/sw-version.ts.
const CACHE = "blog-__BUILD_ID__";
const OFFLINE_URL = "/404.html";
const NAVIGATION_TIMEOUT_MS = 4000;
const OFFLINE_HTML =
  '<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width">' +
  "<title>Offline</title><h1>Offline</h1><p>This page is not saved for offline reading.</p>";

self.addEventListener("install", (event) => {
  // Keep the offline page and manifest ready; posts are cached when visited.
  event.waitUntil(
    caches
      .open(CACHE)
      .then((cache) => cache.addAll([OFFLINE_URL, "/manifest.webmanifest"]))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((names) => Promise.all(names.filter((n) => n !== CACHE).map((n) => caches.delete(n))))
      .then(() => self.clients.claim()),
  );
});

async function store(request, response) {
  if (response.ok || response.type === "opaque") {
    const cache = await caches.open(CACHE);
    await cache.put(request, response.clone());
  }
  return response;
}

async function offlineResponse() {
  const cached = await caches.match(OFFLINE_URL);
  if (cached) return cached;
  return new Response(OFFLINE_HTML, {
    status: 503,
    headers: { "Content-Type": "text/html; charset=utf-8" },
  });
}

// Network first. If the network is slow, show the cached copy while the fetch keeps updating it.
async function handleNavigation(request) {
  const network = fetch(request).then((response) => store(request, response));
  const timeout = new Promise((resolve) => setTimeout(resolve, NAVIGATION_TIMEOUT_MS, null));
  try {
    const first = await Promise.race([network, timeout]);
    if (first) return first;
    return (await caches.match(request)) ?? (await network);
  } catch {
    return (await caches.match(request)) ?? (await offlineResponse());
  }
}

async function cacheFirst(request) {
  const cached = await caches.match(request);
  if (cached) return cached;
  return store(request, await fetch(request));
}

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET" || request.headers.has("range")) return;
  const url = new URL(request.url);

  if (url.origin !== self.location.origin) {
    // Cross-origin: only fonts (for example fonts.gstatic.com), cache first.
    if (request.destination === "font") event.respondWith(cacheFirst(request));
    return;
  }
  if (request.mode === "navigate") {
    event.respondWith(handleNavigation(request));
  } else if (url.pathname.startsWith("/assets/") || url.pathname.startsWith("/_astro/")) {
    event.respondWith(cacheFirst(request));
  }
});
